45	    public ResponseEntity<String> createDocument(@Valid @RequestBody ApiDtos.CreateDocumentRequest request) {
46	        return writeExecutor.execute(request.requestId(), hash("POST /api/documents", request),
47	                () -> WriteResult.of(201, translationService.createDocument(request))).toResponseEntity();
48	    }
49	
50	    /** 增加段落：文档草稿版本加一。 */
51	    @PostMapping("/{documentId}/segments")
52	    public ResponseEntity<String> addSegment(@PathVariable long documentId,
53	                                             @Valid @RequestBody ApiDtos.AddSegmentRequest request) {
54	        String operation = "POST /api/documents/" + documentId + "/segments";
55	        return writeExecutor.execute(request.requestId(), hash(operation, request),
56	                () -> WriteResult.of(201, translationService.addSegment(documentId, request))).toResponseEntity();
57	    }
