14	 */
15	public final class ApiDtos {
16	
17	    private ApiDtos() {
18	    }
19	
20	    /** 初始段落输入。 */
21	    public record SegmentInput(
22	            @NotBlank(message = "segmentId 不能为空") @Size(max = 64) String segmentId,
23	            @NotBlank(message = "sourceText 不能为空") String sourceText) {
24	    }
