26	    /** 建文档请求：1~5 种目标语言，可携带初始段落。 */
27	    public record CreateDocumentRequest(
28	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
29	            @NotNull(message = "targetLanguages 不能为空") @Size(min = 1, max = 5, message = "目标语言须为 1~5 种")
30	            List<@NotBlank(message = "语言码不能为空") String> targetLanguages,
31	            @NotNull(message = "segments 不能为空") List<@Valid SegmentInput> segments) {
32	    }
