1	package com.example.starter.translation;
2	
3	import org.junit.jupiter.api.DisplayName;
4	import org.junit.jupiter.api.Test;
5	
6	import static org.assertj.core.api.Assertions.assertThat;
7	
8	/**
9	 * 多语种段落发布 API 主流程与失败分支测试。
10	 */
11	class TranslationApiTest extends AbstractIntegrationTest {
12	
13	    @Test
14	    @DisplayName("建文档：201，初始草稿版本 1、发布版本 0，语言码归一为小写")
15	    void createDocumentSuccess() throws Exception {
16	        ApiResult result = postJson("/api/documents",
17	                "{\"requestId\":\"" + newRequestId() + "\",\"targetLanguages\":[\"EN\",\"ja\"],"
18	                        + "\"segments\":[{\"segmentId\":\"s1\",\"sourceText\":\"你好世界\"}]}");
19	        assertThat(result.status()).isEqualTo(201);
20	        assertThat(result.body().get("documentId").asLong()).isPositive();
21	        assertThat(result.body().get("draftVersion").asInt()).isEqualTo(1);
22	        assertThat(result.body().get("publishedVersion").asInt()).isEqualTo(0);
23	        assertThat(result.body().get("targetLanguages").toString()).contains("en", "ja");
24	    }
25	
26	    @Test
27	    @DisplayName("建文档：目标语言为 0 或 6 种时返回 400")
28	    void createDocumentInvalidLanguageCount() throws Exception {
29	        ApiResult zero = postJson("/api/documents",
30	                "{\"requestId\":\"" + newRequestId() + "\",\"targetLanguages\":[],\"segments\":[]}");
31	        assertThat(zero.status()).isEqualTo(400);
32	        ApiResult six = postJson("/api/documents",
33	                "{\"requestId\":\"" + newRequestId() + "\",\"targetLanguages\":"
34	                        + "[\"en\",\"ja\",\"fr\",\"de\",\"es\",\"it\"],\"segments\":[]}");
35	        assertThat(six.status()).isEqualTo(400);
36	    }
37	
38	    @Test
39	    @DisplayName("建文档：目标语言重复返回 422，初始段落 segmentId 重复返回 422")
40	    void createDocumentDuplicates() throws Exception {
41	        ApiResult dupLang = postJson("/api/documents",
42	                "{\"requestId\":\"" + newRequestId() + "\",\"targetLanguages\":[\"en\",\"EN\"],\"segments\":[]}");
43	        assertThat(dupLang.status()).isEqualTo(422);
44	        ApiResult dupSegment = postJson("/api/documents",
45	                "{\"requestId\":\"" + newRequestId() + "\",\"targetLanguages\":[\"en\"],"
46	                        + "\"segments\":[{\"segmentId\":\"s1\",\"sourceText\":\"a\"},"
47	                        + "{\"segmentId\":\"s1\",\"sourceText\":\"b\"}]}");
48	        assertThat(dupSegment.status()).isEqualTo(422);
49	    }
50	
51	    @Test
52	    @DisplayName("增加段落：草稿版本加一；重复 segmentId 返回 409")
53	    void addSegmentAndConflict() throws Exception {
54	        long docId = createDocument(newRequestId(), "[\"en\"]", "[]");
55	        ApiResult added = postJson("/api/documents/" + docId + "/segments",
56	                "{\"requestId\":\"" + newRequestId() + "\",\"segmentId\":\"s1\",\"sourceText\":\"第一段\"}");
57	        assertThat(added.status()).isEqualTo(201);
58	        assertThat(added.body().get("sourceVersion").asInt()).isEqualTo(1);
59	        assertThat(added.body().get("draftVersion").asInt()).isEqualTo(2);
60	
61	        ApiResult duplicate = postJson("/api/documents/" + docId + "/segments",
62	                "{\"requestId\":\"" + newRequestId() + "\",\"segmentId\":\"s1\",\"sourceText\":\"重复\"}");
63	        assertThat(duplicate.status()).isEqualTo(409);
64	    }
65	
66	    @Test
67	    @DisplayName("源文修订：源文版本与草稿版本加一；段落不存在返回 404")
68	    void reviseSource() throws Exception {
69	        long docId = createDocument(newRequestId(), "[\"en\"]",
70	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
71	        ApiResult revised = putJson("/api/documents/" + docId + "/segments/s1/source",
72	                "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"修订后\"}");
73	        assertThat(revised.status()).isEqualTo(200);
74	        assertThat(revised.body().get("sourceVersion").asInt()).isEqualTo(2);
75	        assertThat(revised.body().get("draftVersion").asInt()).isEqualTo(2);
76	
77	        ApiResult missing = putJson("/api/documents/" + docId + "/segments/nope/source",
78	                "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"x\"}");
79	        assertThat(missing.status()).isEqualTo(404);
80	    }
81	
82	    @Test
83	    @DisplayName("译文提交：成功；源文版本不匹配 422；语言不在目标语言 422；缺少 X-Actor-Id 400")
84	    void submitTranslation() throws Exception {
85	        long docId = createDocument(newRequestId(), "[\"en\"]",
86	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
87	        ApiResult ok = submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
88	        assertThat(ok.status()).isEqualTo(200);
89	        assertThat(ok.body().get("translationVersion").asInt()).isEqualTo(1);
90	        assertThat(ok.body().get("sourceVersion").asInt()).isEqualTo(1);
91	        assertThat(ok.body().get("draftVersion").asInt()).isEqualTo(2);
92	
93	        ApiResult stale = submitTranslation(docId, "s1", "en", "alice", "hi", 99, newRequestId());
94	        assertThat(stale.status()).isEqualTo(422);
95	
96	        ApiResult wrongLang = submitTranslation(docId, "s1", "fr", "alice", "bonjour", 1, newRequestId());
97	        assertThat(wrongLang.status()).isEqualTo(422);
98	
99	        String body = "{\"requestId\":\"" + newRequestId() + "\",\"content\":\"hi\",\"sourceVersion\":1}";
100	        ApiResult noActor = putJson("/api/documents/" + docId + "/segments/s1/translations/en", body);
101	        assertThat(noActor.status()).isEqualTo(400);
102	    }
103	
104	    @Test
105	    @DisplayName("译文批准：作者不能审核自己的译文 422；译文版本不匹配 422；成功批准")
106	    void approveTranslation() throws Exception {
107	        long docId = createDocument(newRequestId(), "[\"en\"]",
108	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
109	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
110	
111	        ApiResult byAuthor = approve(docId, "s1", "en", "alice", 1, newRequestId());
112	        assertThat(byAuthor.status()).isEqualTo(422);
113	
114	        ApiResult wrongVersion = approve(docId, "s1", "en", "bob", 7, newRequestId());
115	        assertThat(wrongVersion.status()).isEqualTo(422);
116	
117	        ApiResult ok = approve(docId, "s1", "en", "bob", 1, newRequestId());
118	        assertThat(ok.status()).isEqualTo(200);
119	        assertThat(ok.body().get("reviewer").asText()).isEqualTo("bob");
120	    }
121	
122	    @Test
123	    @DisplayName("批准失效：源文修订后旧批准失效，发布 422；重新提交并批准后发布成功")
124	    void approvalInvalidatedBySourceRevision() throws Exception {
125	        long docId = createDocument(newRequestId(), "[\"en\"]",
126	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
127	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
128	        approve(docId, "s1", "en", "bob", 1, newRequestId());
129	
130	        // 修订源文：源文版本 2，旧批准失效
131	        putJson("/api/documents/" + docId + "/segments/s1/source",
132	                "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"新原文\"}");
133	        ApiResult stalePublish = publish(docId, 3, 0, newRequestId());
134	        assertThat(stalePublish.status()).isEqualTo(422);
135	
136	        // 基于旧源文版本提交译文 422；基于当前版本提交后旧批准失效，发布仍 422
137	        ApiResult staleSubmit = submitTranslation(docId, "s1", "en", "alice", "hi", 1, newRequestId());
138	        assertThat(staleSubmit.status()).isEqualTo(422);
139	        ApiResult resubmit = submitTranslation(docId, "s1", "en", "alice", "new hello", 2, newRequestId());
140	        assertThat(resubmit.status()).isEqualTo(200);
141	        assertThat(resubmit.body().get("translationVersion").asInt()).isEqualTo(2);
142	        ApiResult stillStale = publish(docId, 4, 0, newRequestId());
